bookDetail.requestInfo:
@js:
var u = '';
if (params && params.queryInfo) u = params.queryInfo.detailUrl || params.queryInfo.url || '';
if (!u && typeof result === 'string') u = result;
if (!u && result && result.detailUrl) u = result.detailUrl;
if (!u && result && result.url) u = result.url;
if (!u && params && params.responseUrl) u = params.responseUrl;
u = String(u).trim().split(/\s+/)[0] || '';
if (u && u.indexOf('http') !== 0) u = config.host + u;
return {'url': u, 'httpHeaders': config.httpHeaders};

bookDetail.detailUrl:
@js:
if (params && params.queryInfo) {
  if (params.queryInfo.detailUrl) return params.queryInfo.detailUrl;
  if (params.queryInfo.url) return params.queryInfo.url;
}
if (typeof result === 'string') return result;
if (result && result.detailUrl) return result.detailUrl;
if (result && result.url) return result.url;
return '';

bookDetail.desc:
//meta[@property='og:description']/@content||@js:
var t = String(result || '').replace(/\s+/g, ' ').trim();
t = t.replace(/^.*?簡介[：:]/, '').replace(/^.*?简介[：:]/, '');
return t;

bookDetail.url:
