return '';

chapterList.requestInfo:
@js:
var host = String(config.host || 'https://www.wcshuba.com');
var u = '';
if (params && params.queryInfo) u = params.queryInfo.url || params.queryInfo.detailUrl || '';
if (!u && typeof result === 'string') u = result;
if (!u && result && result.url) u = result.url;
if (!u && result && result.detailUrl) u = result.detailUrl;
if (!u && params && params.responseUrl) u = params.responseUrl;
u = String(u).trim().split(/\s+/)[0] || '';
var m = u.match(/\/book\/(\d+)\.html/);
if (m) u = host + '/chapterlist/' + m[1] + '.html';
else if (u.indexOf('/chapterlist/') >= 0) u = u;
else if (u && u.indexOf('http') !== 0) u = host + u;
return {'url': u, 'httpHeaders': config.httpHeaders};

chapterList.nextPageUrl:
//a[@id='index-next-top']/@href||@js:
var cur = String(params.responseUrl || '');
var nxt = String(result || '').trim().split(/\s+/)[0] || '';
if (!nxt) return '';
var cm = cur.match(/\/chapterlist\/(\d+)(?:\/(\d+))?\.html/);
var nm = nxt.match(/\/chapterlist\/(\d+)(?:\/(\d+))?\.html/);
if (!cm || !nm) return '';
if (cm[1] !== nm[1]) return '';
var cp = parseInt(cm[2] || '1', 10);
var np = parseInt(nm[2] || '1', 10);
if (np <= cp) return '';
return nxt;

chapterContent.requestInfo:
@js:
var host = String(config.host || 'https://www.wcshuba.com');
var u = '';
if (params && params.queryInfo) u = params.queryInfo.url || params.queryInfo.detailUrl || '';
if (!u && params && params.lastResponse && params.lastResponse.nextPageUrl) u = params.lastResponse.nextPageUrl;
if (!u && typeof result === 'string') u = result;
if (!u && result && result.url) u = result.url;
if (!u && result && result.detailUrl) u = result.detailUrl;
if (!u && params && params.responseUrl) u = params.responseUrl;
u = String(u).trim().split(/\s+/)[0] || '';
if (u && u.indexOf('http') !== 0) u = host + u;
return {'url': u, 'httpHeaders': config.httpHeaders};

chapterContent.content:
//div[@id='booktxt']||@js:
var html = String(result || '');
html = html.replace(/<div[^>]*id=['"]play['"][^>]*>[\s\S]*?<\/div>/gi, '');
html = html.replace(/<script[\s\S]*?<\/script>/gi, '');
html = html.replace(/<style[\s\S]*?<\/style>/gi, '');
html = html.replace(/<br\s*\/?\s*>/gi, '\n');
html = html.replace(/<\/p>/gi, '\n');
html = html.replace(/<p[^>]*>/gi, '');
html = html.replace(/<[^>]+>/g, '');
html = html.replace(/\r/g, '');
html = html.replace(/\n{3,}/g, '\n\n');
html = html.replace(/^[\s\n]+/, '');
html = html.replace(/[\s\n]+$/, '');
return html.trim();

chapterContent.nextPageUrl:
//a[@rel='next']/@href||@js:
var nxt = String(result || '').trim().split(/\s+/)[0] || '';
if (!nxt) return '';
if (nxt.indexOf('/read/') < 0) return '';
var cur = String(params.responseUrl || '');
var cm = cur.match(/\/read\/(\d+)\/(\d+)\.html/);
var nm = nxt.match(/\/read\/(\d+)\/(\d+)\.html/);
if (!cm || !nm) return '';
if (cm[1] !== nm[1]) return '';
if (nm[2] === cm[2]) return '';
return nxt;

